package br.com.bancohorizonte.controller; import br.com.bancohorizonte.dto.*; import br.com.bancohorizonte.service.ContaService; import java.util.*; public class ContaController {private final ContaService service; public ContaController(ContaService service){this.service=service;} public ContaResponse abrir(AbrirContaRequest r){return service.abrir(r);} public ContaResponse buscar(Long id){return service.buscar(id);} public List<ContaResponse> listarPorPessoa(Long id){return service.listarPorPessoa(id);} public ContaResponse depositar(Long id,MovimentacaoRequest r){return service.depositar(id,r.valor());} public ContaResponse sacar(Long id,MovimentacaoRequest r){return service.sacar(id,r.valor());} }
